/// its name was free when the run looked, and is taken now.
pub const THE_NAME_IS_TAKEN: &str = "something stands at the destination that was not there \
     when this run looked: --ignore-existing keeps it";

/// Create `dst` to write it. With `new_only` — a run that keeps what
/// exists — by a creation that FAILS if the name is taken by anything: a
/// file, a directory, a link to nothing (which a plain creation writes
/// THROUGH, making what it names). Whatever is there is then not this
/// run's to touch.
fn create_to_write(dst: &Path, new_only: bool) -> std::io::Result<std::fs::File> {
    if new_only {
        std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(dst)
    } else {
        std::fs::File::create(dst)
    }
}

/// Ready `dst` to be written (`windows_metadata::prepare_destination`) —
/// but with `new_only`, touch nothing of what stands there (cr-ecm15-1):
/// it is this run's only once the run has made it.
fn prepare_to_write(
    dst: &Path,
    metadata: Option<&crate::generated::WindowsFileMetadata>,
    new_only: bool,
) -> Result<()> {
    if new_only {
        crate::windows_metadata::prepare_new_destination(dst, metadata)
    } else {
        crate::windows_metadata::prepare_destination(dst, metadata)
    }
}

/// Which file a record of one describes, where the system says so in the
/// record itself (Unix: its device and its number there); `None` elsewhere.
fn file_identity(metadata: &std::fs::Metadata) -> Option<(u64, u64)> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt as _;
        Some((metadata.dev(), metadata.ino()))
    }
    #[cfg(not(unix))]
    {
        let _ = metadata;
        None
    }
}

/// Which file stands at `path` now — itself, a link being a link.
fn identity_at(path: &Path) -> Option<(u64, u64)> {
    std::fs::symlink_metadata(path)
        .ok()
        .as_ref()
        .and_then(file_identity)
}

/// cr-ecm16-2: which file a run that keeps what exists made at a name —
/// `None` for any other run, and where the system does not say.
fn claimed_identity(made: &std::fs::File, new_only: bool) -> Option<(u64, u64)> {
    new_only
        .then(|| made.metadata().ok().as_ref().and_then(file_identity))
        .flatten()
}

