        ("one/only", 1),
        ("sp ace", 1),
        ("é.txt", 1),
        ("Z", 1),
        ("_u", 1),
        ("~t", 1),
        ("0n", 1),
        ("-dash", 1),
        ("!bang", 1),
        ("k15", 1500),
        ("m1", 1024 * 1024),
