    std::os::unix::fs::symlink("nowhere", t.join("broken")).unwrap();
    std::os::unix::fs::symlink("ring", t.join("ring")).unwrap();
    std::os::unix::fs::symlink("a.txt/x", t.join("through-a-file")).unwrap();
