#[test]
fn interrupted_resume() {
    let dir=tempdir().unwrap();
    let src=dir.path().join("src");
    fs::write(&src, vec![0x57; 1024]).unwrap();
    fs::set_permissions(&src, fs::Permissions::from_mode(0o600)).unwrap();
    for name in ["fresh", "partial"] {
        let target=dir.path().join(name);
        if name=="partial" {
            fs::write(&target, b"").unwrap();
            fs::set_permissions(&target, fs::Permissions::from_mode(0o644)).unwrap();
        }
        let result=resume_copy_from(&mut fs::File::open(&src).unwrap(),2048,&target,1024);
        assert!(result.is_err());
        let copied=fs::read(&target).unwrap();
        assert_eq!(&copied[..1024], vec![0x57;1024]);
        println!("short source read, {name} partial with 1024 source bytes, mode {:04o}", fs::metadata(&target).unwrap().permissions().mode() & 0o777);
    }
}

#[tokio::test]
async fn abort_at_a_stable_local_alias() {
    let tmp=tempdir().unwrap();
    let root=tmp.path().canonicalize().unwrap();
    let alias=root.join("alias");
    fs::write(root.join("regular"), b"original").unwrap();
    symlink("regular",&alias).unwrap();
    let sink=FsTransferSink::new(root.clone(), root.clone(), FsSinkConfig::default());
    let header=FileHeader {relative_path:"alias".into(), size:32, ..Default::default()};
    let mut writer=sink.begin_record(&header).await.unwrap();
    writer.write(b"part").await.unwrap();
    let result=writer.abort("source read ended").await.unwrap();
    println!("outcome: {result:?}, alias visible: {}, bytes: {:?}",alias.exists(), fs::read(&alias).ok());
}

#[test]
fn cancel_begin_record() {
    let runtime=tokio::runtime::Builder::new_current_thread().enable_all().max_blocking_threads(1).build().unwrap();
    runtime.block_on(async {
        let tmp=tempdir().unwrap();
        let root=tmp.path().canonicalize().unwrap();
        let file=root.join("record");
        let sink=FsTransferSink::new(root.clone(),root,FsSinkConfig{ignore_existing:true,..Default::default()});
        let header=FileHeader{relative_path:"record".into(),size:32,..Default::default()};
        let mut opening=sink.begin_record(&header);
        for _ in 0..16 {
            if file.exists() { break; }
            assert!(opening.as_mut().poll(&mut Context::from_waker(Waker::noop())).is_pending());
            tokio::task::spawn_blocking(|| ()).await.unwrap();
        }
        assert!(file.exists());
        let (ready, started)=tokio::sync::oneshot::channel();
        let (release, wait)=std::sync::mpsc::channel();
        let worker=tokio::task::spawn_blocking(move || {ready.send(()).unwrap(); wait.recv().unwrap();});
        started.await.unwrap();
        let waiting=matches!(opening.as_mut().poll(&mut Context::from_waker(Waker::noop())),Poll::Pending);
        drop(opening);
        release.send(()).unwrap();
        worker.await.unwrap();
        tokio::task::spawn_blocking(|| ()).await.unwrap();
        println!("cancel after create: still awaiting work {waiting}, destination size {:?}", fs::metadata(&file).ok().map(|m|m.len()));
    });
}
