$restored=git hash-object (Join-Path $copy $sinkRel)
if ($restored -ne $expected) { throw 'restored sink differs' }
cargo test -p blit-core --test review_observations -- --nocapture *> (Join-Path $env:TMPDIR 'head-sink-recompiled.log')
$headObs=$LASTEXITCODE
Get-Content (Join-Path $env:TMPDIR 'head-sink-recompiled.log') -Tail 18
"restored head sink $restored, head observations exit $headObs"
